    vec2 diff = point2 - point1;
    float distance = length(diff);
    vec2 direction = diff / distance;

    float t = clamp(dot(view_position - point1, direction) / distance, 0, 1);

    vec4 color = mix(color1, color2, t);

    frag_color = color;
}

