smooth out vec2 uv;
#endif

#if defined(ROUNDED) || defined(BORDERED) || defined(REPEAT)
smooth out vec2 local_position;
#endif

void main()
{
#if defined(TEXTURED) && !defined(REPEAT)
    // Use a_position as a texture coord here
    vec2 texture_position = texture_source_position + a_position * texture_source_size;
    uv = texture_position / texture_size;
#endif

#if !defined(ROUNDED) && !defined(BORDERED) && !defined(REPEAT)
    vec2 local_position;
#endif
    local_position = a_position * size;
    vec2 view_position = position + local_position;
    vec2 clip_space_position = (view_position / viewport) * 2 - 1;
    gl_Position = vec4(clip_space_position, 0, 1);
}

uniform vec4 tint;

out vec4 frag_color;

void main()
{
    frag_color = tint;
}

#ifdef TEXTURED
uniform sampler2D tex;

#ifdef REPEAT
uniform vec2 texture_size;
#endif
#endif

flat in vec4 tint;

#ifdef TEXTURED
#ifdef REPEAT
smooth in vec2 local_position;
flat in vec2 size;
flat in vec2 texture_source_position;
flat in vec2 texture_source_size;
#else
smooth in vec2 uv;
#endif
#endif

out vec4 frag_color;

void main()
{
    vec4 color = tint;

#ifdef TEXTURED
#ifdef REPEAT
    // Use the local position to determine the repeated texture coord, anchoring to the top
    vec2 flipped_position = vec2(local_position.x, size.y - local_position.y);
    vec2 texture_position = texture_source_position + mod(flipped_position, texture_source_size);
    vec2 uv = texture_position / texture_size;
    uv.y = 1 - uv.y;
#endif

    color *= texture(tex, uv);
#endif

    frag_color = color;
}

uniform samplerBuffer instances;

uniform vec2 viewport;
// uniform mat3x2 transform;

// a_position is in range 0,1
layout (location = 0) in vec2 a_position;

flat out vec4 tint;

#ifdef STIPPLED
flat out float stipple_length;
flat out float stipple_on_length;

smooth out float stipple_pos;
#endif

#ifdef SQUIGGLE
flat out float width;

smooth out vec2 line_pos;
#endif

#ifdef ANTIALIAS
#error "Not supported for regular lines"
#endif

void main()
{
#ifdef STIPPLED
    tint = texelFetch(instances, gl_InstanceID * 4 + 0);
    vec4 mat0 = texelFetch(instances, gl_InstanceID * 4 + 1);
    vec4 mat1 = texelFetch(instances, gl_InstanceID * 4 + 2);
    vec4 stipple = texelFetch(instances, gl_InstanceID * 4 + 3);

    float line_length = stipple.x;
    float stipple_offset = stipple.y;
    stipple_length = stipple.z;
    stipple_on_length = stipple.w;
#else
    tint = texelFetch(instances, gl_InstanceID * 3 + 0);
    vec4 mat0 = texelFetch(instances, gl_InstanceID * 3 + 1);
    vec4 mat1 = texelFetch(instances, gl_InstanceID * 3 + 2);

#ifdef SQUIGGLE
    width = mat1.b;
    float line_length = mat1.a;
#endif
#endif

    mat3x2 transform = mat3x2(mat0.rg, mat0.ba, mat1.rg);

    vec2 view_position = (transform * vec3(a_position, 1)).xy;

#ifdef SQUIGGLE
    line_pos = vec2(a_position.x * line_length, a_position.y * width);
#endif

#ifdef STIPPLED
    stipple_pos = (stipple_offset + a_position.x * line_length) / stipple_length;
#endif

    vec2 clip_space_position = (view_position / viewport) * 2 - 1;
    gl_Position = vec4(clip_space_position, 0, 1);
}

